 const values=await page.locator('#portal-scope svg.recharts-surface').evaluateAll(es=>es.map(e=>({theme:e.closest('[data-prism-theme]')?.getAttribute('data-prism-theme'),fills:[...e.querySelectorAll('.recharts-bar-rectangle path')].map(p=>getComputedStyle(p).fill)})));
 assert.equal(values.length,2);const expected={light:'rgb(30, 136, 229)',paper:'rgb(30, 136, 229)',dark:'rgb(98, 172, 237)',blueprint:'rgb(29, 95, 191)','blueprint-night':'rgb(134, 197, 255)'};
