roundProbes['nested-styles']=async(page,row)=>{
 // CSS isolation check on rendered copies, including a preview root that itself matches the selector.
 // This is not a second React Theme Context / business-runtime integration claim.
 const selectors=['[data-agent-preview]','[data-agent-message="user"]','.bp-frame-card','.bp-section-card','[data-agent-relation-view]','[data-agent-arranger-view]'];
 return page.evaluate(({selectors,theme})=>{
  const source=selectors.flatMap(s=>[...document.querySelectorAll(s)]).filter(e=>e.getClientRects().length).slice(0,16);if(!source.length)throw Error('No rendered isolation samples');
  const props=['backgroundColor','color','borderRadius','borderTop','borderRight','borderBottom','borderLeft','boxShadow','outline','outlineOffset','fontSize','lineHeight'];
  const measure=root=>[root,...root.querySelectorAll('*')].map(e=>[null,'::before','::after'].map(p=>{const s=getComputedStyle(e,p);return props.map(k=>s[k]);}));
  const results=[];for(const original of source){const outer=document.createElement('div'),clone=original.cloneNode(true);outer.style.width='600px';outer.dataset.prismTheme=theme;clone.setAttribute('data-agent-preview','');clone.dataset.prismTheme=theme;clone.querySelectorAll('[id]').forEach(e=>e.removeAttribute('id'));clone.removeAttribute('id');outer.append(clone);document.body.append(outer);try{const baseline=measure(clone);for(const outerTheme of ['light','paper','dark','blueprint','blueprint-night']){outer.dataset.prismTheme=outerTheme;const actual=measure(clone);results.push({selector:original.tagName,inner:theme,outer:outerTheme,nodes:actual.length,equal:JSON.stringify(actual)===JSON.stringify(baseline)});}}finally{outer.remove();}}
  if(!results.every(r=>r.equal))throw Error('Rendered-copy nested style mismatch: '+JSON.stringify(results.filter(r=>!r.equal)));return results;
 },{selectors,theme:row.theme});
};
