 const geometry=await page.locator('.bp-fact-container dl,.bp-fact-container dl > *').evaluateAll(es=>es.map(e=>({width:e.clientWidth,scroll:e.scrollWidth,font:getComputedStyle(e).fontSize})));assert.ok(geometry.every(x=>x.scroll<=x.width+1));return {independent:values,geometry};
