roundProbes['night-buttons']=async(page,row,ctx)=>{const primary=button(page,'次要按钮示例');await primary.hover();const hover=await snapshot(primary);const trigger=button(page,'清空演示备注');const old=await page.locator('[data-blueprint-component="Popover"]').innerText();await trigger.click();const danger=button(page,'确认清空本页示例');const values=await snapshot(danger);if(row.theme==='blueprint-night'){assert.equal(hover[0].background,'rgb(22, 48, 90)');assert.equal(values[0].background,'rgb(255, 112, 112)');assert.equal(values[0].color,'rgb(8, 19, 34)');}await ctx.capture(page,row,'-danger');await button(page,'保留本页备注').click();assert.equal(await page.locator('[data-blueprint-component="Popover"]').innerText(),old);return {hover,danger:values,cancelPreserved:true};};
roundProbes['formal-tabs']=async(page,row)=>{const list=page.getByRole('tablist').first(),tabs=list.getByRole('tab');assert.ok(await tabs.count()>=2);const first=tabs.first();await first.focus();await first.press('ArrowRight');await page.keyboard.press('Enter');const selected=await list.locator('[aria-selected="true"]').innerText();assert.ok(selected);const disabled=list.locator('[aria-disabled="true"],button:disabled');const values=[];for(const d of await disabled.all()){await d.focus();await d.press('Enter');assert.notEqual(await d.getAttribute('aria-selected'),'true');values.push(await d.innerText());}return {selected,disabled:values};};
roundProbes['heatmap-zero']=async(page,row,ctx)=>{const chart=page.locator('#compact-heatmap [data-chart-engine="echarts"]').first();await chart.scrollIntoViewIfNeeded();await chart.locator('svg').waitFor();const value=await chart.evaluate(async el=>(await import('/docs/blueprint/evidence/matrix-closeout-20261019/review-fixture.tsx')).zeroCell(el));assert.ok(Array.isArray(value.point)&&value.point.length===2);await chart.click({position:{x:value.point[0],y:value.point[1]}});await poll(page,({rowLabel,columnLabel})=>[...document.querySelectorAll('#compact-heatmap svg text')].some(e=>e.textContent.includes(`${rowLabel} · ${columnLabel}`)),value.data);const text=await chart.locator('svg text').allTextContents();assert.ok(text.some(t=>/^0$/.test(t)));await ctx.capture(page,row,'-zero-tooltip');return {...value,text};};
roundProbes['prompt-portals']=async(page,row,ctx)=>{const root=page.locator('[data-agent-prompt-bar]'),out=[];for(const name of ['添加附件与来源','选择模型：本机规则','开始听写','开始语音对话']){const trigger=button(root,name);await trigger.click();const popup=root.locator('[data-slot="menu-popup"]:visible,[data-slot="popover-popup"]:visible');await popup.waitFor();const value=await popup.evaluate(e=>({theme:e.closest('[data-prism-theme]')?.getAttribute('data-prism-theme'),inside:!!e.closest('[data-agent-prompt-bar]'),text:e.textContent}));assert.equal(value.theme,row.theme);assert.ok(value.inside);await ctx.capture(page,row,`-portal-${out.length}`);const h=await popup.elementHandle();await page.keyboard.press('Escape');await hiddenNode(page,h);await focused(page,trigger);out.push({name,...value});}return out;};
roundProbes['question-card']=async(page)=>{const region=page.locator('#existing-agent-inputs');const heading=region.getByRole('heading',{name:'这次需要整理哪些内容？',exact:true});await heading.waitFor();const card=heading.locator('xpath=ancestor::*[@data-slot="card"][1]');assert.match(await card.innerText(),/补充一个信息/);assert.doesNotMatch(await card.innerText(),/需要你确认/);await card.getByRole('radio').first().click();const input=card.getByPlaceholder('也可以补充自己的要求');await input.fill('保留原题与公式');assert.match(await region.innerText(),/已选择：.*尚未执行任务/);return {text:await card.innerText(),draft:await input.inputValue()};};
async function presentationTabs(page){const list=page.locator('[data-agent-component-page] > [data-slot="tabs"] [data-slot="tabs-list"]').first();return await list.count()?list:page.getByRole('tablist').first();}
roundProbes['execution']=async(page,row)=>{const list=await presentationTabs(page),out=[];const tabs=list.getByRole('tab');for(const tab of await tabs.all()){const name=await tab.innerText();if(!/对话|专用|紧凑|状态|扩展/.test(name))continue;await tab.click();const preview=page.locator('[data-agent-preview]');await preview.waitFor();const text=await preview.innerText();assert.ok(text.trim());out.push({name,text,actions:await preview.getByRole('button').allTextContents()});}assert.ok(out.length>=3);return out;};
roundProbes['old-agent-calls']=async(page,row,ctx)=>{const out=[];for(const slug of ['file-input','execution-confirmation','collection-basket']){const session=await ctx.open(row.theme,row.viewport.width,`/next/components/agent-components/${slug}`);try{const values=await roundProbes.execution(session.page,row,ctx);out.push({slug,values});}finally{await session.context.close();}}return out;};
roundProbes['overlay-regression']=async(page,row,ctx)=>{const out=[];for(const route of ['/next/components/dialog-layout','/next/components/record-list','/next/components/tree','/next/components/evidence-matrix','/next/components/box-plot']){const session=await ctx.open(row.theme,row.viewport.width,route);try{const p=session.page,trigger=p.locator('main [aria-haspopup="dialog"]:visible,main [aria-haspopup="menu"]:visible,main [role="combobox"]:visible').first();assert.ok(await trigger.count(),`No real popup trigger on ${route}`);await trigger.click();const popup=p.locator('[data-slot="dialog-popup"]:visible,[data-slot="menu-popup"]:visible,[data-slot="select-popup"]:visible,[data-slot="combobox-popup"]:visible').last();await popup.waitFor();const value={route,theme:await popup.evaluate(e=>e.closest('[data-prism-theme]')?.getAttribute('data-prism-theme')),text:await popup.innerText()};assert.equal(value.theme,row.theme);const h=await popup.elementHandle();await p.keyboard.press('Escape');await hiddenNode(p,h);await focused(p,trigger);out.push(value);}finally{await session.context.close();}}return out;};
roundProbes['arranger-interactions']=async(page,row)=>{await page.getByRole('button',{name:'展开编排',exact:true}).first().click();const card=page.locator('[data-agent-arranger-view="workspace"]').first();await card.waitFor();const rows=card.locator('[data-arranger-row] [id$="-title"]'),before=await rows.allTextContents();const down=card.locator('[data-arranger-action="down"]:not(:disabled)').first();await down.click();const after=await rows.allTextContents();assert.notDeepEqual(after,before);await card.locator('[data-arranger-action="up"]:not(:disabled)').first().click();assert.deepEqual(await rows.allTextContents(),before);const group=card.getByRole('combobox',{name:'移到分组末尾',exact:true}).first();await group.click();await page.getByRole('option').last().click();assert.notDeepEqual(await rows.allTextContents(),before);const confirm=card.locator('[data-arranger-action="confirm"]');assert.equal(await confirm.count(),1);const state={disabled:await confirm.isDisabled(),description:await confirm.getAttribute('aria-describedby')};if(state.disabled)assert.ok(state.description);else{await confirm.click();assert.match(await page.locator('[data-agent-preview]').innerText(),/保存状态未改变/);}await button(card,'返回原位置').click();await page.locator('[data-agent-arranger-view="inline"]').first().waitFor();return {before,after,confirm:state};};
roundProbes['relation-interactions']=async(page,row)=>{await button(page,'查看关系图').first().click();const card=page.locator('[data-agent-relation-view="workspace"]').first();await card.waitFor();const filter=role(card,'group','按类型筛选').getByRole('button');assert.ok(await filter.count()>1);await filter.nth(1).click();assert.equal(await filter.nth(1).getAttribute('aria-pressed'),'true');await filter.first().click();const node=card.locator('[aria-label="节点与关系列表"] button').first();await node.click();const detail=role(card,'region','选中节点的邻接关系');await detail.waitFor();const text=await detail.innerText();const source=button(detail,'查看来源');if(await source.count()){await source.click();assert.match(await page.locator('[data-agent-preview]').innerText(),/来源|请求/);}await button(card,'返回原位置').click();await page.locator('[data-agent-relation-view="inline"]').first().waitFor();return {text,filterApplied:true,returned:true};};
// Visual preparation performs actual state changes; screenshots never mark an obligation passed.
roundProbes['visual-portals']=async(page,row,ctx)=>{await choose(page,'局部主题',labels[row.theme]);await button(page,'局部对话框').click();await page.locator('[data-slot="dialog-popup"]:visible').waitFor();await ctx.capture(page,row,'-dialog');await page.keyboard.press('Escape');await page.locator('[data-slot="dialog-popup"]:visible').waitFor({state:'hidden'});await button(page,'局部材料操作').click();const sub=role(page,'menuitem','材料示例子菜单');await sub.focus();await sub.press('ArrowRight');await page.getByRole('menuitem',{name:'长中文讲评材料示例',exact:true}).waitFor();await ctx.capture(page,row,'-submenu');return {states:['dialog','submenu']};};
roundProbes['visual-cards']=async(page,row,ctx)=>{await page.locator('#object-section-cards .bp-frame-card-title').evaluate(e=>e.textContent='非常长的中文原件名称与条件说明 '+ 'Continuous_English_File_Name_'.repeat(6)+'.pdf');await ctx.capture(page,row,'-long-title');return {injected:'long Chinese and continuous English filename'};};
roundProbes['visual-workspace']=async(page,row,ctx)=>{const output=await roundProbes['material-states'](page,row,ctx);await roundProbes['confirmation-states'](page,row,ctx);await roundProbes.basket(page,row,ctx);return {materialStates:output.length};};
roundProbes['visual-common']=async(page,row,ctx)=>{const s=page.locator('#common-components'),input=s.locator('input').and(s.getByLabel('材料名称 · 必填校验',{exact:true}));await keyboard(page,input);await ctx.capture(page,row,'-invalid-focus');await button(s,'打开演示对话框').click();await page.locator('[data-slot="dialog-popup"]:visible').waitFor();await ctx.capture(page,row,'-dialog');return {states:['invalid-focus','dialog']};};
roundProbes['visual-batch-two']=async(page,row,ctx)=>{const s=page.locator('#common-components-two');const input=s.locator('input').and(s.getByLabel('材料关键词',{exact:true}));await keyboard(page,input);await ctx.capture(page,row,'-group-focus');for(const [name,slot]of [['打开样例菜单','menu-popup'],['打开长内容侧面板','sheet-popup']]){await button(s,name).click();const popup=page.locator(`[data-slot="${slot}"]:visible`);await popup.waitFor();await ctx.capture(page,row,`-${slot}`);const h=await popup.elementHandle();await page.keyboard.press('Escape');await hiddenNode(page,h);}await button(s,'信息通知样例').click();await button(s,'关闭信息状态样例').waitFor();await ctx.capture(page,row,'-toast');return {states:['group-focus','menu','sheet','toast']};};
roundProbes['visual-fonts']=async(page,row,ctx)=>{await ctx.capture(page,row,'-loaded');const session=await ctx.open(row.theme,row.viewport.width,foundation,{blockFont:true});try{await ctx.capture(session.page,row,'-blocked');return {blocked:true};}finally{await session.context.close();}};
